create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(char_length(username) between 2 and 32),display_name text not null default 'VYBE user',avatar_url text,created_at timestamptz not null default now());
create table if not exists public.channels(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,youtube_channel_id text unique,name text not null,description text default '',avatar_url text,banner_url text,created_at timestamptz not null default now());
create table if not exists public.videos(id uuid primary key default gen_random_uuid(),channel_id uuid references public.channels(id) on delete cascade,youtube_video_id text unique,title text not null,description text default '',thumbnail_url text,embed_url text,direct_mp4_url text,duration_seconds integer,published_at timestamptz,view_count bigint not null default 0,created_at timestamptz not null default now(),check(youtube_video_id is not null or direct_mp4_url is not null));
create table if not exists public.subscriptions(user_id uuid references auth.users(id) on delete cascade,channel_id uuid references public.channels(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,channel_id));
create table if not exists public.video_likes(user_id uuid references auth.users(id) on delete cascade,video_id uuid references public.videos(id) on delete cascade,value smallint not null check(value in(-1,1)),created_at timestamptz not null default now(),primary key(user_id,video_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),video_id uuid not null references public.videos(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,parent_id uuid references public.comments(id) on delete cascade,body text not null check(char_length(body) between 1 and 2000),pinned boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.comment_likes(user_id uuid references auth.users(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,comment_id));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null,title text not null,body text not null default '',target_url text,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.playlists(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 1 and 100),is_public boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.playlist_videos(playlist_id uuid references public.playlists(id) on delete cascade,video_id uuid references public.videos(id) on delete cascade,position integer not null default 0,added_at timestamptz not null default now(),primary key(playlist_id,video_id));
create table if not exists public.watch_history(user_id uuid references auth.users(id) on delete cascade,video_id uuid references public.videos(id) on delete cascade,watched_at timestamptz not null default now(),primary key(user_id,video_id));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,comment_id uuid references public.comments(id) on delete cascade,video_id uuid references public.videos(id) on delete cascade,reason text not null,status text not null default 'pending',created_at timestamptz not null default now(),check(comment_id is not null or video_id is not null));
do $$ declare t text; begin foreach t in array array['profiles','channels','videos','subscriptions','video_likes','comments','comment_likes','notifications','playlists','playlist_videos','watch_history','reports'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles readable" on public.profiles for select using(true);
create policy "profile owner writes" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "channels readable" on public.channels for select using(true);
create policy "channel owner writes" on public.channels for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "videos readable" on public.videos for select using(true);
create policy "video owner writes" on public.videos for all using(exists(select 1 from public.channels c where c.id=channel_id and c.owner_id=auth.uid())) with check(exists(select 1 from public.channels c where c.id=channel_id and c.owner_id=auth.uid()));
create policy "subscriptions own rows" on public.subscriptions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "likes readable" on public.video_likes for select using(true);
create policy "likes owner insert" on public.video_likes for insert with check(auth.uid()=user_id);
create policy "likes owner delete" on public.video_likes for delete using(auth.uid()=user_id);
create policy "comments readable" on public.comments for select using(true);
create policy "signed comment insert" on public.comments for insert with check(auth.uid()=user_id);
create policy "comment owner update" on public.comments for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "comment owner delete" on public.comments for delete using(auth.uid()=user_id);
create policy "comment likes owner" on public.comment_likes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "notifications owner" on public.notifications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "playlist select" on public.playlists for select using(is_public or auth.uid()=user_id);
create policy "playlist owner writes" on public.playlists for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "playlist video select" on public.playlist_videos for select using(exists(select 1 from public.playlists p where p.id=playlist_id and (p.is_public or p.user_id=auth.uid())));
create policy "playlist video owner" on public.playlist_videos for all using(exists(select 1 from public.playlists p where p.id=playlist_id and p.user_id=auth.uid())) with check(exists(select 1 from public.playlists p where p.id=playlist_id and p.user_id=auth.uid()));
create policy "history owner" on public.watch_history for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "reports insert" on public.reports for insert with check(auth.uid()=reporter_id);
create policy "reports own read" on public.reports for select using(auth.uid()=reporter_id);
